   112→            <Block
   113→              flexDirection={isUser ? "row" : "row-reverse"}
   114→              gap={4}
   115→              align="center"
   116→            >
   117→              <PinIndicator event={event} />
   118→              <Text size={TextSize.tiny} color={Colors.white50}>
