   144→                width={7}
   145→                height={6}
   146→                style={styles.polygon}
   147→              />
   148→            </Block>
   149→          )}
   150→        </Block>
   151→      </MessageLongPressWrapper>
   152→      <SeenBy seenBy={seenBy} messageWidth={messageWidth} />
   153→    </Block>
   154→  );
   155→};
