export type FlexAttributes = {
    [K in FilteredFlexKeys]?: ViewStyle[K];
} & {
    gap?: ViewStyle["gap"];
    rowGap?: ViewStyle["rowGap"];
    columnGap?: ViewStyle["columnGap"];
